float hash21(vec2 p){
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){
    vec2  res = u_resolution;
    vec2  p   = (fragCoord * 2.0 - res) / min(res.x, res.y);
    float t   = u_time * u_speed;
    float au  = u_audio_bass;

    float HZ = 0.06;                       // horizon
    float h  = p.y - HZ;

    // ---------- sky ----------
    vec3 col = mix(vec3(1.00, 0.42, 0.55),
                   vec3(0.30, 0.05, 0.44), smoothstep(0.0, 0.55, h));
    col = mix(col, vec3(0.020, 0.010, 0.100), smoothstep(0.35, 1.30, h));

    // ---------- stars ----------
    vec2  sid = floor(p * 30.0);
    float sh  = hash21(sid);
    if (sh > 0.962 && h > 0.25){
        vec2 sf = fract(p * 30.0) - 0.5;
        vec2 so = vec2(hash21(sid + 3.17), hash21(sid + 7.71)) - 0.5;
        col += vec3(0.90, 0.95, 1.00)
             * (1.0 - smoothstep(0.0, 0.10, length(sf - so * 0.6)))
             * smoothstep(0.25, 0.90, h)
             * (0.5 + 0.5 * sin(t * 2.0 + sh * 40.0));
    }

    // ---------- banded sun ----------
    float sunR = 0.30 + au * 0.02;
    vec2  sp   = vec2(p.x, h - 0.34);
    float sd   = length(sp);
    float disc = 1.0 - smoothstep(sunR - 0.006, sunR, sd);
    float k    = smoothstep(sunR, -sunR, sp.y);              // 0 top -> 1 bottom
    float f    = fract(sp.y * (3.0 + 15.0 * k));
    float gapT = 0.10 + 0.60 * k;
    float sun  = disc * smoothstep(gapT - 0.10, gapT + 0.10, f);
    vec3  sunC = mix(vec3(1.00, 0.88, 0.30), vec3(1.00, 0.14, 0.46),
                     smoothstep(sunR, -sunR, sp.y));
    col = mix(col, sunC, sun);
    col += sunC * 0.30 * exp(-max(sd - sunR, 0.0) * 5.5) * (0.5 + au);

    // ---------- mountain silhouette (sky only, drawn before the grid) ------
    float r1 = 0.075 + 0.055 * sin(p.x * 2.7 + 1.3)
                   + 0.030 * sin(p.x * 6.1 - 0.7)
                   + 0.016 * sin(p.x * 11.0 + 2.2);
    float r2 = r1 * 0.55 + 0.030;
    if (h > 0.0){
        if (h < r1){
            col = mix(col, vec3(0.045, 0.015, 0.100), 0.92);
            col += u_color2 * 0.16 * exp(-max(r1 - h, 0.0) * 45.0);
        }
        if (h < r2) col = mix(col, vec3(0.010, 0.005, 0.045), 0.95);
    }

    // ---------- perspective grid ----------
    if (h < 0.0){
        float fz   = 1.0 / max(-h, 0.0012);
        vec2  guv  = vec2(p.x * fz * 0.42, fz * 0.30 - t * 0.55);
        vec2  gl   = abs(fract(guv) - 0.5);
        float g    = 1.0 - smoothstep(0.0, 0.055, min(gl.x, gl.y));
        float fade = smoothstep(0.0, 0.22, -h);
        col = mix(col, vec3(0.055, 0.010, 0.130), fade * 0.80);
        col += mix(u_color2, u_accent, 0.5) * g * fade * (1.7 + au * 1.4);
        col += sunC * exp(-abs(p.x) * 2.2) * fade * (0.16 + 0.26 * g);
    }

    // ---------- CRT grade ----------
    col *= 0.94 + 0.06 * sin(fragCoord.y * 3.14159);
    col  = pow(max(col, 0.0), vec3(0.92));
    col *= 1.0 - 0.22 * dot(p * 0.55, p * 0.55);
    fragColor = vec4(col, 1.0);
}

